enum {
  // Log module ID for the Platform.
  kLogModuleIDPlatform = 0,
};

// Log module for the Platform.
static const LogModule kLogModulePlatform = {
    .id = kLogModuleIDPlatform,
    .name = "PLATFORM",
};

#include "cpu.h"
